"""Intersection model with stateful traffic signals.

Each intersection has 4 incoming lanes (N/S/E/W), each with a signal whose
phase cycle drives vehicle crossing. UCP proposes green extensions and the
Intersection Controller executes them.
"""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from enum import Enum
from typing import Optional


class SignalColor(str, Enum):
    RED = "red"
    YELLOW = "yellow"
    GREEN = "green"


@dataclass
class Signal:
    direction: str
    color: SignalColor = SignalColor.RED
    phase_started_at: float = field(default_factory=time.time)
    extension_seconds: float = 0.0

    def age_seconds(self, now: float) -> float:
        return now - self.phase_started_at

    def to_dict(self) -> dict:
        return {
            "direction": self.direction,
            "color": self.color.value,
            "age_seconds": round(self.age_seconds(time.time()), 2),
            "extension_seconds": self.extension_seconds,
        }


@dataclass
class Intersection:
    """A four-way intersection with a 4-phase traffic controller."""

    id: str
    x: float
    y: float
    cycle_seconds: float = 60.0
    green_seconds: float = 12.0
    yellow_seconds: float = 3.0
    main_axis: tuple[str, str] = ("north", "south")
    signals: dict[str, Signal] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.signals:
            for d in ("north", "south", "east", "west"):
                initial = SignalColor.GREEN if d in self.main_axis else SignalColor.RED
                self.signals[d] = Signal(direction=d, color=initial)

    def tick(self, dt: float, now: float) -> None:
        """Advance the signal phases. The list of directions acts as a
        rotating cycle. Yellow is rendered for yellow_seconds; then the axis
        flips."""
        for sig in self.signals.values():
            sig.extension_seconds = max(0.0, sig.extension_seconds - dt)
            age = sig.age_seconds(now)
            # compute expected duration for its current color
            if sig.color == SignalColor.YELLOW:
                if age >= self.yellow_seconds:
                    self._flip(sig, now)
            elif sig.color == SignalColor.GREEN:
                if age >= self.green_seconds + sig.extension_seconds:
                    sig.color = SignalColor.YELLOW
                    sig.phase_started_at = now
                    sig.extension_seconds = 0.0

    def _flip(self, sig: Signal, now: float) -> None:
        other_color = (
            SignalColor.RED if sig.color == SignalColor.GREEN else SignalColor.GREEN
        )
        # cross flip: the partner axis gets the same new state
        partner = None
        for other_sig in self.signals.values():
            if other_sig.direction != sig.direction and other_sig.color != sig.color:
                partner = other_sig
                break
        sig.color = other_color
        sig.phase_started_at = now
        if partner:
            partner.color = other_color
            partner.phase_started_at = now

    def apply_extension(self, direction: str, seconds: float, now: float) -> None:
        sig = self.signals[direction]
        if sig.color == SignalColor.GREEN:
            sig.extension_seconds = max(sig.extension_seconds, seconds)

    def density(self) -> dict[str, int]:
        """Filled in by the simulator -- kept on the intersection object for
        easy introspection."""
        return getattr(self, "_density", {})

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "x": self.x,
            "y": self.y,
            "cycle_seconds": self.cycle_seconds,
            "green_seconds": self.green_seconds,
            "yellow_seconds": self.yellow_seconds,
            "signals": {k: v.to_dict() for k, v in self.signals.items()},
            "density": self.density(),
        }

"""Pathfinding algorithms used by the route optimization agent."""

from __future__ import annotations

import heapq
from typing import Callable, Optional


def dijkstra(graph: dict[str, dict[str, float]], start: str, goal: str) -> tuple[list[str], float]:
    """Classic Dijkstra shortest-path; returns route + cumulative cost."""
    distances: dict[str, float] = {n: float("inf") for n in graph}
    distances[start] = 0.0
    prev: dict[str, Optional[str]] = {n: None for n in graph}
    pq: list[tuple[float, str]] = [(0.0, start)]
    visited: set[str] = set()

    while pq:
        d, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        if node == goal:
            break
        for nb, w in graph.get(node, {}).items():
            nd = d + w
            if nd < distances[nb]:
                distances[nb] = nd
                prev[nb] = node
                heapq.heappush(pq, (nd, nb))

    if distances[goal] == float("inf"):
        return [], float("inf")

    route: list[str] = []
    cur: Optional[str] = goal
    while cur is not None:
        route.append(cur)
        cur = prev[cur]
    route.reverse()
    return route, distances[goal]


def astar(graph: dict[str, dict[str, float]], start: str, goal: str, heuristic: Callable[[str, str], float]) -> tuple[list[str], float]:
    """A* search with a user-supplied heuristic."""
    g: dict[str, float] = {n: float("inf") for n in graph}
    g[start] = 0.0
    f: dict[str, float] = {n: float("inf") for n in graph}
    f[start] = heuristic(start, goal)
    prev: dict[str, Optional[str]] = {n: None for n in graph}
    open_set: list[tuple[float, str]] = [(f[start], start)]
    closed: set[str] = set()

    while open_set:
        _, node = heapq.heappop(open_set)
        if node in closed:
            continue
        closed.add(node)
        if node == goal:
            break
        for nb, w in graph.get(node, {}).items():
            tentative = g[node] + w
            if tentative < g[nb]:
                g[nb] = tentative
                f[nb] = tentative + heuristic(nb, goal)
                prev[nb] = node
                heapq.heappush(open_set, (f[nb], nb))

    if g[goal] == float("inf"):
        return [], float("inf")
    route: list[str] = []
    cur: Optional[str] = goal
    while cur is not None:
        route.append(cur)
        cur = prev[cur]
    route.reverse()
    return route, g[goal]

"""Specialized traffic algorithms: Dynamic Priority Aging, Deadlock/Gridlock
prevention, queue optimization, and Digital Twin coordination."""

from __future__ import annotations

from dataclasses import dataclass


def dynamic_priority_aging(base_priority: float, waiting_seconds: float, k: float = 0.05) -> float:
    """A vehicle's effective priority grows with waiting time so that a
    starved low-priority vehicle eventually jumps the queue."""
    return float(base_priority) + max(0.0, waiting_seconds) * k


def detect_gridlock(density_per_lane: dict[str, int], threshold: int = 12) -> bool:
    """Gridlock = a majority of lanes simultaneously saturated."""
    if not density_per_lane:
        return False
    saturated = sum(1 for v in density_per_lane.values() if v >= threshold)
    return saturated >= max(3, len(density_per_lane) // 2 + 1)


def detect_spillback(downstream_queue: int, threshold: int = 14) -> bool:
    return downstream_queue >= threshold


def detect_starvation(waiting_seconds: float, threshold: float = 90.0) -> bool:
    return waiting_seconds >= threshold


def deadlock_check(signals: dict[str, str]) -> dict[str, bool]:
    """A junction is deadlocked if all approaches are red and no path exists.

    Returns a dict describing which axes are simultaneously blocked.
    """
    n = signals.get("north", "red")
    s = signals.get("south", "red")
    e = signals.get("east", "red")
    w = signals.get("west", "red")
    return {
        "ns_blocked": n == "red" and s == "red",
        "ew_blocked": e == "red" and w == "red",
        "fully_blocked": all(v == "red" for v in (n, s, e, w)),
    }


def queue_optimization(queues: list[int], capacity: int) -> dict[str, float]:
    """Suggest green-time splits proportional to queue length."""
    total = sum(max(0, q) for q in queues) or 1
    splits = [max(0.0, q) / total for q in queues]
    total_cycle = 60.0
    greens = [round(s * total_cycle * 0.9, 1) for s in splits]  # 90% of cycle to greens
    return {"splits": splits, "greens": greens}


def digital_twin_diff(sim_metrics: dict, twin_metrics: dict) -> dict[str, float]:
    """Compare live and digital-twin metrics to surface drift."""
    diff: dict[str, float] = {}
    for k in sim_metrics:
        if k in twin_metrics:
            diff[k] = round(float(sim_metrics[k]) - float(twin_metrics[k]), 3)
    return diff


def queue_length_estimate(v_stopped: int, v_moving: int) -> float:
    """Queue length = stopped + at-risk-of-stopping moving."""
    return float(v_stopped) + 0.5 * float(v_moving)

