import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import App from "./App.jsx";
import "./index.css";

ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </React.StrictMode>
);

import React, { useEffect } from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import Sidebar from "./components/layout/Sidebar.jsx";
import Topbar from "./components/layout/Topbar.jsx";
import VoiceFAB from "./components/layout/VoiceFAB.jsx";
import { useLiveStream } from "./hooks/useLiveStream.js";
import DashboardPage from "./pages/DashboardPage.jsx";
import SimulationPage from "./pages/SimulationPage.jsx";
import TwinPage from "./pages/TwinPage.jsx";
import AgentsPage from "./pages/AgentsPage.jsx";
import FlowPage from "./pages/FlowPage.jsx";
import PredictionPage from "./pages/PredictionPage.jsx";
import AnalyticsPage from "./pages/AnalyticsPage.jsx";
import AlgorithmsPage from "./pages/AlgorithmsPage.jsx";
import HistoryPage from "./pages/HistoryPage.jsx";
import AlertsPage from "./pages/AlertsPage.jsx";
import ReportsPage from "./pages/ReportsPage.jsx";
import SettingsPage from "./pages/SettingsPage.jsx";

export default function App() {
  const { connected, scenario, setScenario, last, agents, kpis, scenarios, alerts, prediction } =
    useLiveStream();

  useEffect(() => {
    document.title = `METRO-FLOW AI — ${scenario?.toUpperCase() || "LIVE"}`;
  }, [scenario]);

  return (
    <div className="min-h-screen flex">
      <Sidebar connected={connected} scenario={scenario} />

      <main className="flex-1 min-w-0 flex flex-col">
        <Topbar
          connected={connected}
          scenario={scenario}
          onScenario={setScenario}
          scenarios={scenarios}
          cityHealth={kpis?.city_health_score ?? last?.metrics?.city_health_score ?? 0}
        />

        <div className="flex-1 min-h-0 overflow-auto px-6 pb-12 pt-2">
          <Routes>
            <Route path="/" element={<Navigate to="/dashboard" replace />} />
            <Route path="/dashboard" element={<DashboardPage last={last} agents={agents} kpis={kpis} alerts={alerts} />} />
            <Route path="/simulation" element={<SimulationPage last={last} />} />
            <Route path="/twin" element={<TwinPage last={last} />} />
            <Route path="/agents" element={<AgentsPage agents={agents} />} />
            <Route path="/agents/flow" element={<FlowPage agents={agents} />} />
            <Route path="/prediction" element={<PredictionPage prediction={prediction} last={last} />} />
            <Route path="/analytics" element={<AnalyticsPage last={last} agents={agents} />} />
            <Route path="/algorithms" element={<AlgorithmsPage />} />
            <Route path="/history" element={<HistoryPage />} />
            <Route path="/alerts" element={<AlertsPage alerts={alerts} last={last} />} />
            <Route path="/reports" element={<ReportsPage kpis={kpis} agents={agents} last={last} />} />
            <Route path="/settings" element={<SettingsPage scenario={scenario} onScenario={setScenario} scenarios={scenarios} />} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </Routes>
        </div>
      </main>

      <VoiceFAB />
    </div>
  );
}

import { useEffect, useRef, useState, useCallback } from "react";

// Hook: maintains a live WebSocket connection to the backend orchestrator
// and exposes the latest snapshot, agent results, alerts, and predictions.
export function useLiveStream() {
  const [connected, setConnected] = useState(false);
  const [last, setLast] = useState(null);
  const [agents, setAgents] = useState([]);
  const [kpis, setKpis] = useState(null);
  const [scenarios, setScenarios] = useState([]);
  const [scenario, setScenario] = useState("normal");
  const [alerts, setAlerts] = useState([]);
  const [prediction, setPrediction] = useState(null);
  const ringRef = useRef([]); // last N snapshots for history
  const wsRef = useRef(null);

  const refresh = useCallback(async () => {
    try {
      const [snapR, agR, scR, alR, prR] = await Promise.all([
        fetch("/api/snapshot").then((r) => r.json()),
        fetch("/api/agents").then((r) => r.json()),
        fetch("/api/scenarios").then((r) => r.json()),
        fetch("/api/alerts").then((r) => r.json()),
        fetch("/api/prediction").then((r) => r.json()),
      ]);
      if (snapR?.tick) setLast(snapR);
      if (Array.isArray(agR)) setAgents(agR);
      // pull KPI bundle from Dashboard Agent
      const dash = Array.isArray(agR) ? agR.find((a) => a.agent_name === "Dashboard Agent") : null;
      if (dash?.output) setKpis(dash.output);
      if (Array.isArray(scR)) setScenarios(scR);
      if (snapR?.scenario) setScenario(snapR.scenario);
      if (alR?.alerts) setAlerts(alR.alerts);
      if (prR && Object.keys(prR).length) setPrediction(prR);
    } catch (e) {
      // ignore — connection is best-effort
    }
  }, []);

  useEffect(() => {
    let timerId;
    refresh();
    timerId = setInterval(refresh, 1500);

    // try web socket
    const proto = window.location.protocol === "https:" ? "wss" : "ws";
    const wsUrl = `${proto}://${window.location.host}/ws`;
    let ws;
    try {
      ws = new WebSocket(wsUrl);
      wsRef.current = ws;
      ws.onopen = () => setConnected(true);
      ws.onclose = () => setConnected(false);
      ws.onerror = () => setConnected(false);
      ws.onmessage = (ev) => {
        try {
          const data = JSON.parse(ev.data);
          if (data.snapshot) setLast(data.snapshot);
          if (Array.isArray(data.agents)) setAgents(data.agents);
          if (data.snapshot?.scenario) setScenario(data.snapshot.scenario);
          // append to ring buffer
          ringRef.current = [...ringRef.current, data].slice(-180);
        } catch (e) {
          // ignore malformed frames
        }
      };
    } catch (e) {
      setConnected(false);
    }
    return () => {
      clearInterval(timerId);
      try { ws?.close(); } catch (_) {}
    };
  }, [refresh]);

  const setScenarioAndSend = useCallback(async (s) => {
    setScenario(s);
    try {
      await fetch("/api/scenario", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ scenario: s }),
      });
    } catch (e) { /* ignore */ }
  }, []);

  const ring = ringRef.current; // for HistoryPage consumers

  return { connected, last, agents, kpis, scenarios, scenario, setScenario: setScenarioAndSend, alerts, prediction, ring, refresh };
}

