function fmt(n, suffix = "") {
  if (n === null || n === undefined || Number.isNaN(n)) return "—";
  if (Math.abs(n) >= 1000) return `${(n / 1000).toFixed(1)}k${suffix}`;
  return `${Number(n).toFixed(suffix ? 0 : 1)}${suffix}`;
}

