import React, { useEffect, useMemo, useState } from "react";
import Section from "../components/ui/Section.jsx";
import { Cpu, Pause, Play, RefreshCw } from "lucide-react";

const HUE_FOR_DIR = {
  north: "#22e0ff",
  south: "#8b5cf6",
  east: "#22d3a5",
  west: "#f5b942",
};

const COLOR_FOR_TYPE = {
  car: "#22e0ff",
  bike: "#60a5fa",
  bus: "#ff5d7a",
  truck: "#f59e0b",
  auto: "#22d3a5",
  ambulance: "#ff4b4b",
  fire_truck: "#fb923c",
  police: "#3b82f6",
  vip_convoy: "#a78bfa",
  pedestrian: "#94a3b8",
  cyclist: "#facc15",
};

// Map the simulator's coordinate system into a 2D canvas: lanes are 0..250m
// from a per-intersection origin. We render lanes as 250px-long bars.
export default function SimulationPage({ last }) {
  const [paused, setPaused] = useState(false);
  const [hover, setHover] = useState(null);
  const intersections = last?.intersections || {};
  const lanes = last?.lanes || {};

  // Build the rail network
  const network = useMemo(() => {
    const grid = {};
    Object.keys(intersections).forEach((id) => {
      grid[id] = intersections[id];
    });
    return grid;
  }, [intersections]);

  return (
    <div className="space-y-4">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-[22px] font-semibold">Live Simulation</h1>
          <p className="text-[12px] text-slate-400">3×3 intersection grid · 12 inbound lanes · physics-based</p>
        </div>
        <div className="flex items-center gap-2">
          <span className="pill-cyan">scenario: {last?.scenario}</span>
          <button onClick={() => setPaused((p) => !p)} className="px-3 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 hover:border-neon-cyan/40 text-[12px] flex items-center gap-2">
            {paused ? <Play className="h-3.5 w-3.5" /> : <Pause className="h-3.5 w-3.5" />}
            {paused ? "Resume" : "Pause"}
          </button>
          <button onClick={() => window.location.reload()} className="px-3 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 hover:border-neon-violet/40 text-[12px] flex items-center gap-2">
            <RefreshCw className="h-3.5 w-3.5" />
            Restart
          </button>
        </div>
      </header>

      <Section title="UrbanVerse Topology" subtitle="vehicles position · velocity · queue state · signal state" icon={Cpu}>
        <div className="relative">
          <svg viewBox="-50 -50 1100 1100" className="w-full h-[720px] rounded-xl bg-ink-800/40 border border-white/5">
            <defs>
              <linearGradient id="roadGrad" x1="0" x2="1" y1="0" y2="1">
                <stop offset="0%" stopColor="#1c264c" />
                <stop offset="100%" stopColor="#0a1024" />
              </linearGradient>
              <pattern id="hatch" patternUnits="userSpaceOnUse" width="10" height="10">
                <path d="M0,10 L10,0" stroke="rgba(255,255,255,0.08)" strokeWidth="1" />
              </pattern>
            </defs>

            {/* Background grid */}
            {Array.from({ length: 4 }).map((_, i) => (
              <line key={`gx-${i}`} x1={i * 250} y1={0} x2={i * 250} y2={750} stroke="rgba(255,255,255,0.05)" />
            ))}
            {Array.from({ length: 4 }).map((_, i) => (
              <line key={`gy-${i}`} x1={0} y1={i * 250} x2={750} y2={i * 250} stroke="rgba(255,255,255,0.05)" />
            ))}

            {/* Roads */}
            {[250, 500, 750].map((x) => (
              <rect key={`hx-${x}`} x={x - 14} y={0} width={28} height={750} fill="url(#roadGrad)" />
            ))}
            {[250, 500, 750].map((y) => (
              <rect key={`hy-${y}`} x={0} y={y - 14} width={750} height={28} fill="url(#roadGrad)" />
            ))}

            {/* Intersection boxes */}
            {Object.entries(network).map(([iid, inter]) => (
              <g key={iid} transform={`translate(${inter.x},${inter.y})`}>
                <rect x={-22} y={-22} width={44} height={44} fill="#121a36" stroke="rgba(255,255,255,0.18)" rx={4} />
                <text x={0} y={-26} textAnchor="middle" fontSize="10" fill="rgba(255,255,255,0.7)" fontFamily="JetBrains Mono">
                  {iid}
                </text>
                {/* signal dots */}
                {Object.entries(inter.signals).map(([dir, s]) => {
                  const positions = {
                    north: [0, -16], south: [0, 16], east: [16, 0], west: [-16, 0],
                  };
                  const [x, y] = positions[dir] || [0, 0];
                  const color = s.color === "green" ? "#22d3a5" : s.color === "yellow" ? "#f5b942" : "#ff5d7a";
                  return (
                    <circle key={dir} cx={x} cy={y} r={3} fill={color} />
                  );
                })}
              </g>
            ))}

            {/* Vehicles */}
            {Object.entries(lanes).flatMap(([iid, dirMap]) =>
              Object.entries(dirMap).flatMap(([dir, lane]) =>
                (lane.vehicles || []).map((v, idx) => {
                  const i = intersections[iid];
                  const px = (() => {
                    // map direction to canvas coords
                    const off = v.position; // 0..245 m → px
                    switch (dir) {
                      case "north": return [i.x - 6, i.y - off];
                      case "south": return [i.x + 6, i.y + off];
                      case "east": return [i.x + off, i.y - 6];
                      case "west": return [i.x - off, i.y + 6];
                      default: return [i.x, i.y];
                    }
                  })();
                  const c = COLOR_FOR_TYPE[v.type] || "#ffffff";
                  const isEmergency = v.is_emergency;
                  return (
                    <g key={`${iid}-${dir}-${v.id}`} transform={`translate(${px[0]},${px[1]})`}
                       onMouseEnter={() => setHover({ v, iid, dir })} onMouseLeave={() => setHover(null)}>
                      <rect x={-4} y={-7} width={8} height={14} rx={2} fill={c}
                            opacity={v.queue_state === "queued" ? 0.7 : 1}>
                        {isEmergency && (
                          <animate attributeName="opacity" values="1;0.4;1" dur="0.8s" repeatCount="indefinite" />
                        )}
                      </rect>
                      {!isEmergency && v.queue_state === "queued" && (
                        <circle cx={0} cy={0} r={2} fill={c} />
                      )}
                    </g>
                  );
                })
              )
            )}
          </svg>

          {/* Hover tooltip */}
          {hover && (
            <div className="absolute top-4 right-4 glass-strong p-3 w-64 z-10">
              <div className="text-[11px] uppercase tracking-[0.18em] text-slate-400">Vehicle</div>
              <div className="font-mono text-[12px] text-neon-cyan">{hover.v.id}</div>
              <div className="text-[11px] mt-1 text-slate-300">
                <div>Type: <span className="text-white">{hover.v.type}</span></div>
                <div>Speed: <span className="text-white">{hover.v.velocity?.toFixed(2)} m/s</span></div>
                <div>Position: <span className="text-white">{hover.v.position?.toFixed(1)} m</span></div>
                <div>Signal: <span className="text-white">{hover.v.signal_state}</span></div>
                <div>Queue: <span className="text-white">{hover.v.queue_state}</span></div>
                <div>Priority: <span className="text-white">{hover.v.base_priority}</span></div>
                <div>Wait: <span className="text-white">{hover.v.waiting_time?.toFixed(1)} s</span></div>
              </div>
            </div>
          )}

          {/* Legend */}
          <div className="absolute bottom-4 left-4 glass-soft px-3 py-2 flex flex-wrap gap-2">
            {Object.entries(COLOR_FOR_TYPE).slice(0, 8).map(([k, c]) => (
              <span key={k} className="text-[10px] flex items-center gap-1.5">
                <span style={{ background: c }} className="h-2 w-3 rounded-sm" />
                <span className="text-slate-300">{k}</span>
              </span>
            ))}
          </div>
        </div>
      </Section>
    </div>
  );
}

import React, { useRef, useMemo, Suspense } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls, Html, Stars, Cloud } from "@react-three/drei";
import * as THREE from "three";
import Section from "../components/ui/Section.jsx";
import { Boxes, Sun, Moon, CloudRain } from "lucide-react";
import clsx from "clsx";

const COLOR_FOR_TYPE = {
  car: "#22e0ff",
  bike: "#60a5fa",
  bus: "#ff5d7a",
  truck: "#f59e0b",
  auto: "#22d3a5",
  ambulance: "#ff4b4b",
  fire_truck: "#fb923c",
  police: "#3b82f6",
  vip_convoy: "#a78bfa",
  pedestrian: "#94a3b8",
  cyclist: "#facc15",
};

const SCALE = 0.6; // 1 lane meter → 0.6 scene units

function Building({ position, height, width, depth, hue = "#1c264c" }) {
  return (
    <mesh position={position}>
      <boxGeometry args={[width, height, depth]} />
      <meshStandardMaterial color={hue} metalness={0.35} roughness={0.6} emissive={"#0a1024"} emissiveIntensity={0.25} />
      {/* glow strip on rooflines */}
      <mesh position={[0, height / 2 + 0.05, 0]}>
        <boxGeometry args={[width + 0.04, 0.04, depth + 0.04]} />
        <meshBasicMaterial color={"#22e0ff"} toneMapped={false} opacity={0.6} transparent />
      </mesh>
    </mesh>
  );
}

function Tree({ position }) {
  return (
    <group position={position}>
      <mesh position={[0, 0.5, 0]}>
        <cylinderGeometry args={[0.15, 0.2, 1, 6]} />
        <meshStandardMaterial color={"#3f2d1f"} />
      </mesh>
      <mesh position={[0, 1.4, 0]}>
        <sphereGeometry args={[0.7, 8, 8]} />
        <meshStandardMaterial color={"#1ec76b"} emissive={"#0ea35b"} emissiveIntensity={0.2} />
      </mesh>
    </group>
  );
}

function Road({ orientation, position, length = 28 }) {
  return (
    <group position={position}>
      <mesh rotation={[0, 0, orientation === "y" ? 0 : Math.PI / 2]}>
        <boxGeometry args={[length, 0.05, 1.4]} />
        <meshStandardMaterial color={"#0a1024"} metalness={0.4} roughness={0.5} />
      </mesh>
      <mesh rotation={[0, 0, orientation === "y" ? 0 : Math.PI / 2]} position={[0, 0.03, 0]}>
        <boxGeometry args={[length, 0.06, 0.05]} />
        <meshBasicMaterial color={"rgba(255,255,255,0.6)"} toneMapped={false} />
      </mesh>
    </group>
  );
}

function TrafficLight({ position, color }) {
  const c = color === "green" ? "#22d3a5" : color === "yellow" ? "#f5b942" : "#ff5d7a";
  return (
    <group position={position}>
      <mesh position={[0, 0.6, 0]}>
        <cylinderGeometry args={[0.08, 0.08, 1.2, 8]} />
        <meshStandardMaterial color={"#10162e"} />
      </mesh>
      <mesh position={[0, 1.3, 0]}>
        <sphereGeometry args={[0.16, 12, 12]} />
        <meshBasicMaterial color={c} toneMapped={false} />
      </mesh>
    </group>
  );
}

function Vehicle({ position, color, length, isEmergency }) {
  const ref = useRef();
  useFrame((_, dt) => {
    if (ref.current) {
      ref.current.material.emissiveIntensity = isEmergency ? 2 + Math.sin(performance.now() / 200) : 0.4;
    }
  });
  return (
    <group position={position}>
      <mesh ref={ref}>
        <boxGeometry args={[length, 0.25, 0.7]} />
        <meshStandardMaterial
          color={color}
          emissive={color}
          emissiveIntensity={isEmergency ? 2 : 0.4}
          metalness={0.6}
          roughness={0.3}
        />
      </mesh>
    </group>
  );
}

function Scene({ last, dusk }) {
  const intersections = last?.intersections || {};
  const lanes = last?.lanes || {};

  const scale = SCALE;
  const interPos = useMemo(() => Object.fromEntries(
    Object.entries(intersections).map(([iid, v]) => [iid, [v.x * scale, 0, v.y * scale]])
  ), [intersections]);

  // layout buildings per cell (between intersections)
  const buildingSeeds = useMemo(() => {
    const out = [];
    Object.values(interPos).forEach(([x, _y, z]) => {
      out.push([x + 6, z - 4, 4, 5]);
      out.push([x - 6, z + 4, 3, 6]);
      out.push([x + 4, z + 6, 5, 4]);
      out.push([x - 4, z - 6, 3.5, 5]);
    });
    return out;
  }, [interPos]);

  return (
    <>
      {/* ambient + key lights */}
      <ambientLight intensity={dusk ? 0.25 : 0.6} color={dusk ? "#7080ff" : "#ffffff"} />
      <directionalLight position={[10, 14, 6]} intensity={dusk ? 0.6 : 1.1} color={dusk ? "#a8b1ff" : "#fff7e6"} />
      <pointLight position={[20, 8, -20]} color={"#22e0ff"} intensity={0.6} />

      {/* ground */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.05, 0]} receiveShadow>
        <planeGeometry args={[140, 140]} />
        <meshStandardMaterial color={dusk ? "#0a1124" : "#0c1530"} metalness={0.2} roughness={0.85} />
      </mesh>

      {/* building geometry clustered around each intersection */}
      {buildingSeeds.map((b, i) => (
        <Building key={`b-${i}`} position={[b[0], b[1] / 2, b[2]]} height={b[1]} width={b[3]} depth={2.5} />
      ))}
      {buildingSeeds.slice(0, 8).map((b, i) => (
        <Tree key={`t-${i}`} position={[b[0] + Math.sin(i) * 1.5, 0, b[2] + Math.cos(i) * 1.5]} />
      ))}

      {/* roads between intersections */}
      {Object.values(interPos).flatMap(([x, _y, z]) => [20, -20]).map((dx, i) => (
        <Road key={`rdx-${i}`} orientation="x" position={[x / 2, 0, z + dx * 0.0]} />
      ))}
      {[0, 0].map((_, i) => null)}
      {/* horizontal roads */}
      {Array.from(new Set(Object.values(interPos).map((p) => p[2]))).flatMap((z) => (
        [-20, -9, 0, 9, 20].map((x) => (
          <Road key={`hroad-${z}-${x}`} orientation="x" position={[x * scale, 0, z + (z > 0 ? 0 : 0)]} length={7} />
        ))
      ))}
      {/* vertical roads */}
      {Array.from(new Set(Object.values(interPos).map((p) => p[0]))).flatMap((x) => (
        [-20, -9, 0, 9, 20].map((z) => (
          <Road key={`vroad-${x}-${z}`} orientation="y" position={[x, 0, z * scale]} length={7} />
        ))
      ))}

      {/* Traffic lights at each intersection */}
      {Object.entries(intersections).flatMap(([iid, inter]) => {
        const [x, _y, z] = interPos[iid];
        return Object.entries(inter.signals).map(([dir, s]) => {
          const offs = {
            north: [0, 0, -1.1],
            south: [0, 0, 1.1],
            east: [1.1, 0, 0],
            west: [-1.1, 0, 0],
          }[dir] || [0, 0, 0];
          return (
            <TrafficLight key={`tl-${iid}-${dir}`} position={[x + offs[0], 0, z + offs[2]]} color={s.color} />
          );
        });
      })}

      {/* vehicles */}
      {Object.entries(lanes).flatMap(([iid, dirMap]) => {
        const [xi, _yi, zi] = interPos[iid];
        return Object.entries(dirMap).flatMap(([dir, lane]) => {
          const off = (v) => {
            switch (dir) {
              case "north": return [xi - 0.4, 0.135, zi - v.position * scale];
              case "south": return [xi + 0.4, 0.135, zi + v.position * scale];
              case "east": return [xi + v.position * scale, 0.135, zi - 0.4];
              case "west": return [xi - v.position * scale, 0.135, zi + 0.4];
              default: return [xi, 0, zi];
            }
          };
          return (lane.vehicles || []).map((v) => {
            const [px, py, pz] = off(v);
            const c = COLOR_FOR_TYPE[v.type] || "#ffffff";
            return (
              <Vehicle
                key={`v-${iid}-${dir}-${v.id}`}
                position={[px, py, pz]}
                color={c}
                length={Math.max(0.6, Math.min(2.6, v.length * SCALE))}
                isEmergency={v.is_emergency}
              />
            );
          });
        });
      })}

      {/* Sky / Night mood */}
      {dusk && <Stars radius={80} depth={50} count={1200} factor={4} fade speed={0.3} />}
      {last?.weather?.rain && <Clouds3D />}
    </>
  );
}

