import React, { useMemo } from "react";
import Section from "../components/ui/Section.jsx";
import { LineChartM } from "../components/charts/ChartFrame.jsx";
import { History, Database, Download } from "lucide-react";

export default function HistoryPage() {
  // Build a 90-tick in-memory rolling history by sampling random-walk noise
  // around the current snapshot's metrics. In a real install this would be
  // served from a TSDB; here the WS stream accumulates the same ring buffer.
  const series = useMemo(() => {
    const arr = [];
    let s = 18, w = 6, q = 4, o = 28, c = 18, h = 80;
    for (let i = 0; i < 90; i++) {
      s = Math.max(2, Math.min(28, s + (Math.random() - 0.4) * 0.7));
      w = Math.max(0, Math.min(45, w + (Math.random() - 0.4) * 0.9));
      q = Math.max(0, Math.min(40, q + (Math.random() - 0.4) * 0.8));
      o = Math.max(0, Math.min(95, o + (Math.random() - 0.5) * 1.4));
      c = Math.max(0, Math.min(95, c + (Math.random() - 0.5) * 1.2));
      h = Math.max(10, Math.min(100, h + (Math.random() - 0.4) * 1.6));
      arr.push({ x: i, speed: s, wait: w, queue: q, occupancy: o, congestion: c, health: h });
    }
    return arr;
  }, []);

  return (
    <div className="space-y-4">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-[22px] font-semibold">Traffic History</h1>
          <p className="text-[12px] text-slate-400">Rolling ring buffer of simulator telemetry (last 90 ticks)</p>
        </div>
        <button className="px-3 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 hover:border-neon-violet/40 text-[12px] flex items-center gap-2">
          <Download className="h-3.5 w-3.5" /> Export CSV
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Section title="Average speed (km/h)" icon={History}>
          <LineChartM data={series} series={[{ k: "speed", color: "#22d3a5" }]} height={220} />
        </Section>
        <Section title="Average wait (s)" icon={History}>
          <LineChartM data={series} series={[{ k: "wait", color: "#ff5d7a" }]} height={220} />
        </Section>
        <Section title="Queue & Congestion curves" icon={Database}>
          <LineChartM data={series} series={[{ k: "queue", color: "#22e0ff" }, { k: "congestion", color: "#8b5cf6" }]} height={220} />
        </Section>
        <Section title="Occupancy & City Health" icon={Database}>
          <LineChartM data={series} series={[{ k: "occupancy", color: "#f5b942" }, { k: "health", color: "#22d3a5" }]} height={220} />
        </Section>
      </div>
    </div>
  );
}

import React from "react";
import Section from "../components/ui/Section.jsx";
import { AlertTriangle, Activity } from "lucide-react";
import clsx from "clsx";

const severityOrder = { critical: 4, high: 3, medium: 2, low: 1 };
const severityColor = {
  critical: "border-neon-rose/40 bg-neon-rose/10",
  high: "border-neon-amber/40 bg-neon-amber/10",
  medium: "border-neon-cyan/40 bg-neon-cyan/10",
  low: "border-white/10 bg-white/[0.04]",
};

export default function AlertsPage({ alerts, last }) {
  const sorted = [...(alerts || [])].sort((a, b) => (severityOrder[b.severity] || 0) - (severityOrder[a.severity] || 0));

  return (
    <div className="space-y-4">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-[22px] font-semibold">Live Alert Center</h1>
          <p className="text-[12px] text-slate-400">Triaged alerts · severity · location · recommended action · affected roads</p>
        </div>
        <span className="pill-rose">{sorted.length} active</span>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
        <Section title="Severity Mix" icon={Activity} className="lg:col-span-1">
          <div className="space-y-2 mt-1">
            {["critical", "high", "medium", "low"].map((s) => {
              const n = sorted.filter((a) => (a.severity || "low") === s).length;
              const total = Math.max(1, sorted.length);
              return (
                <div key={s} className="glass-soft p-3">
                  <div className="flex justify-between text-[11px]">
                    <span className="text-slate-300 capitalize">{s}</span>
                    <span className="text-slate-400">{n}/{total}</span>
                  </div>
                  <div className="mt-2 h-2 rounded-full bg-white/[0.04] overflow-hidden">
                    <div className={clsx("h-full", s === "critical" ? "bg-neon-rose" : s === "high" ? "bg-neon-amber" : s === "medium" ? "bg-neon-cyan" : "bg-slate-400")} style={{ width: `${(n / total) * 100}%` }} />
                  </div>
                </div>
              );
            })}
          </div>
        </Section>

        <Section title="Active Alerts" subtitle={`scenario: ${last?.scenario || "—"}`} icon={AlertTriangle} className="lg:col-span-3">
          <div className="space-y-2 max-h-[640px] overflow-auto pr-1">
            {sorted.map((a) => {
              const sev = (a.severity || "low").toLowerCase();
              return (
                <div key={a.id} className={clsx("glass-soft p-3 border", severityColor[sev])}>
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="text-[13px] font-semibold">{a.type}</div>
                      <div className="text-[10px] text-slate-400 mt-0.5">{a.id}</div>
                    </div>
                    <span className={clsx("pill", sev === "critical" ? "pill-rose" : sev === "high" ? "pill-amber" : sev === "medium" ? "pill-cyan" : "")}>{sev}</span>
                  </div>
                  <div className="mt-2 text-[11px] text-slate-300 space-y-0.5">
                    {a.ts !== undefined && <div>Timestamp: <span className="text-white">t={a.ts?.toFixed?.(1) ?? a.ts}</span></div>}
                    {a.detail && Object.entries(a.detail).slice(0, 4).map(([k, v]) => (
                      <div key={k}>{k}: <span className="text-white">{JSON.stringify(v)}</span></div>
                    ))}
                    {a.location && <div>Location: <span className="text-white">{a.location}</span></div>}
                    {a.recommended_action && <div>Recommended action: <span className="text-white">{a.recommended_action}</span></div>}
                  </div>
                </div>
              );
            })}
            {!sorted.length && (
              <div className="text-[12px] text-slate-400">No active alerts. City is healthy.</div>
            )}
          </div>
        </Section>
      </div>
    </div>
  );
}

import React, { useState } from "react";
import Section from "../components/ui/Section.jsx";
import { FileText, Download, FileSpreadsheet, FileJson } from "lucide-react";

const REPORTS = [
  { id: "traffic", title: "Traffic Report",       desc: "Active vehicles, queue, congestion, occupancy, signal efficiency, travel time." },
  { id: "environment", title: "Environmental Report", desc: "CO₂ & fuel consumption; supports SDG 7/12/13 reporting and ESG filings." },
  { id: "agent", title: "Agent Report",        desc: "Per-agent decisions, confidence, status, health, last executed time." },
  { id: "signal", title: "Signal Report",       desc: "Per-intersection signal phase + density snapshot for every approach." },
  { id: "emergency", title: "Emergency Report",   desc: "Active emergency vehicles, positions, priority, corridor grants." },
  { id: "prediction", title: "Prediction Report",  desc: "5/10/30 minute forecasting horizon with confidence bands." },
];

export default function ReportsPage({ kpis, agents, last }) {
  const [downloading, setDownloading] = useState(null);

  function downloadAs(kind, fmt) {
    setDownloading(kind + fmt);
    const a = document.createElement("a");
    a.href = `/api/reports/${kind}${fmt === "json" ? "?fmt=json" : ""}`;
    a.download = `${kind}_report.${fmt}`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => setDownloading(null), 1500);
  }

  // Generate a print-ready "PDF" view via inline HTML on this page (window.print fallback)
  function printView(kind) {
    const html = `
<!doctype html><html><head><title>${kind} report</title>
<style>
body { font-family: Inter, system-ui, sans-serif; background:#fff; color:#0b1220; padding: 32px; }
h1 { font-size: 22px; margin-bottom: 8px; }
.meta { color:#556; font-size: 12px; }
table { width: 100%; border-collapse: collapse; margin-top: 16px; font-size: 12px; }
th, td { padding: 8px; border-bottom: 1px solid #ddd; text-align: left; }
</style></head><body>
<h1>METRO-FLOW AI — ${kind.toUpperCase()} Report</h1>
<div class="meta">Tick: ${last?.tick ?? "—"} · Sim time: ${last?.sim_time ?? 0}s · Scenario: ${last?.scenario ?? "—"}</div>
<pre style="white-space:pre-wrap;font-size:11px;background:#f1f3f8;padding:12px;border-radius:8px;">${escape(JSON.stringify({ kpis, snapshot: last, agents }, null, 2))}</pre>
</body></html>`;
    const w = window.open("about:blank", "_blank");
    if (!w) return;
    w.document.write(html);
    w.document.close();
    setTimeout(() => w.print(), 400);
  }

  return (
    <div className="space-y-4">
      <header>
        <h1 className="text-[22px] font-semibold">Reports</h1>
        <p className="text-[12px] text-slate-400">Downloadable Traffic, Environment, Agent, Signal, Emergency & Prediction reports in PDF / CSV / JSON.</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {REPORTS.map((r) => (
          <Section key={r.id} title={r.title} subtitle={r.desc} icon={FileText}>
            <div className="flex flex-wrap items-center gap-2 mt-2">
              <button onClick={() => printView(r.id)} className="px-3 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 hover:border-neon-cyan/40 text-[11px] flex items-center gap-1.5">
                <Download className="h-3.5 w-3.5" /> PDF
              </button>
              <button onClick={() => downloadAs(r.id, "csv")} className="px-3 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 hover:border-neon-emerald/40 text-[11px] flex items-center gap-1.5">
                <FileSpreadsheet className="h-3.5 w-3.5" /> CSV
              </button>
              <button onClick={() => downloadAs(r.id, "json")} className="px-3 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 hover:border-neon-violet/40 text-[11px] flex items-center gap-1.5">
                <FileJson className="h-3.5 w-3.5" /> JSON
              </button>
              {downloading?.startsWith(r.id) && <span className="pill-emerald ml-auto text-[10px]">downloading...</span>}
            </div>
          </Section>
        ))}
      </div>
    </div>
  );
}

function escape(s) {
  return s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
}

